// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public {
        c = new MONEY_BOX();
        c.Initialized();
    }
    function testFuzz_property(uint256 _val) public {
        vm.assume(_val > 0);
        bool ok;
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "SetMinSum should revert after initialization");
    }
}
